package com.docuflow.service;
import com.docuflow.dto.DocumentDtos.*; import com.docuflow.entity.*; import com.docuflow.exception.ApiException; import com.docuflow.repository.*; import java.io.*; import java.nio.file.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile;
@Service @Transactional
public class DocumentService {
 private final DocumentRepository docs; private final UserRepository users; private final CommentRepository comments; private final ActivityLogRepository activity; private final Path storage;
 public DocumentService(DocumentRepository docs,UserRepository users,CommentRepository comments,ActivityLogRepository activity,@Value("${app.storage-dir}") String storage){this.docs=docs;this.users=users;this.comments=comments;this.activity=activity;this.storage=Paths.get(storage).toAbsolutePath().normalize();}
 public DocumentResponse upload(CreateRequest req,MultipartFile file,User owner){if(file.isEmpty()||!"application/pdf".equals(file.getContentType()))throw new ApiException(HttpStatus.BAD_REQUEST,"Only PDF files are accepted");try{Files.createDirectories(storage);String stored=UUID.randomUUID()+".pdf";Files.copy(file.getInputStream(),storage.resolve(stored));var doc=new Document(req.title().trim(),req.description(),stored,Objects.requireNonNullElse(file.getOriginalFilename(),"document.pdf"),file.getSize(),owner);var reviewers=users.findAllById(req.reviewerIds());if(reviewers.size()!=new HashSet<>(req.reviewerIds()).size())throw new ApiException(HttpStatus.BAD_REQUEST,"One or more reviewers do not exist");doc.setReviewers(reviewers);docs.save(doc);log(doc,owner,"DOCUMENT_UPLOADED","Pending approval");return map(doc);}catch(IOException e){throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR,"Unable to store document");}}
 @Transactional(readOnly=true) public Page<DocumentResponse> list(User user,String search,Pageable page){return docs.visibleTo(user,user.getRole()==Role.ADMINISTRATOR,search==null?"":search,page).map(this::map);}
 @Transactional(readOnly=true) public DocumentResponse get(Long id,User user){return map(access(id,user));}
 public DocumentResponse decide(Long id,DecisionRequest req,User user){var doc=access(id,user);var approval=doc.getApprovals().stream().filter(a->a.getReviewer().getId().equals(user.getId())).findFirst().orElseThrow(()->new ApiException(HttpStatus.FORBIDDEN,"You are not assigned as a reviewer"));if(approval.getDecision()!=ApprovalDecision.PENDING)throw new ApiException(HttpStatus.CONFLICT,"You have already decided");approval.decide(req.decision());if(req.decision()==ApprovalDecision.REJECTED)doc.setStatus(DocumentStatus.REJECTED);else if(doc.getApprovals().stream().allMatch(a->a.getDecision()==ApprovalDecision.APPROVED))doc.setStatus(DocumentStatus.READY_FOR_SIGNATURE);log(doc,user,req.decision()==ApprovalDecision.APPROVED?"APPROVED":"REJECTED","Document review decision recorded");return map(doc);}
 public DocumentResponse sign(Long id,User user){var doc=access(id,user);if(doc.getStatus()!=DocumentStatus.READY_FOR_SIGNATURE)throw new ApiException(HttpStatus.CONFLICT,"Document is not ready for finalization");if(user.getRole()!=Role.ADMINISTRATOR&&user.getRole()!=Role.MANAGER)throw new ApiException(HttpStatus.FORBIDDEN,"Only a manager or administrator may finalize");doc.setStatus(DocumentStatus.SIGNED);log(doc,user,"DOCUMENT_FINALIZED","Workflow completed");return map(doc);}
 public DocumentResponse archive(Long id,User user){var doc=access(id,user);if(doc.getStatus()!=DocumentStatus.SIGNED)throw new ApiException(HttpStatus.CONFLICT,"Only finalized documents can be archived");if(user.getRole()!=Role.ADMINISTRATOR&&user.getRole()!=Role.MANAGER)throw new ApiException(HttpStatus.FORBIDDEN,"Only a manager or administrator may archive");doc.setStatus(DocumentStatus.ARCHIVED);log(doc,user,"DOCUMENT_ARCHIVED","Document archived");return map(doc);}
 public DocumentResponse rename(Long id,RenameRequest request,User user){var doc=access(id,user);if(!doc.getOwner().getId().equals(user.getId())&&user.getRole()!=Role.ADMINISTRATOR)throw new ApiException(HttpStatus.FORBIDDEN,"Only the owner or administrator may rename");doc.rename(request.title().trim());log(doc,user,"DOCUMENT_RENAMED","Title changed");return map(doc);}
 public CommentResponse comment(Long id,CommentRequest req,User user){var doc=access(id,user);var comment=comments.save(new Comment(doc,user,req.content().trim()));log(doc,user,"COMMENT_ADDED","Comment added");return new CommentResponse(user.getFullName(),comment.getContent(),comment.getCreatedAt());}
 @Transactional(readOnly=true) public List<CommentResponse> comments(Long id,User user){access(id,user);return comments.findByDocumentIdOrderByCreatedAtAsc(id).stream().map(c->new CommentResponse(c.getAuthor().getFullName(),c.getContent(),c.getCreatedAt())).toList();}
 public void delete(Long id,User user){var doc=access(id,user);if(user.getRole()!=Role.ADMINISTRATOR&&!doc.getOwner().getId().equals(user.getId()))throw new ApiException(HttpStatus.FORBIDDEN,"Only the owner or administrator may delete");docs.delete(doc);try{Files.deleteIfExists(storage.resolve(doc.getStoredFileName()));}catch(IOException ignored){}}
 @Transactional(readOnly=true) public org.springframework.core.io.Resource file(Long id,User user){var doc=access(id,user);try{return new org.springframework.core.io.UrlResource(storage.resolve(doc.getStoredFileName()).toUri());}catch(java.net.MalformedURLException e){throw new ApiException(HttpStatus.NOT_FOUND,"File not found");}}
 @Transactional(readOnly=true) public List<ActivityResponse> activity(Long id,User user){access(id,user);return activity.findTop20ByDocumentIdOrderByCreatedAtDesc(id).stream().map(a->new ActivityResponse(a.getActor().getFullName(),a.getAction(),a.getDetail(),a.getCreatedAt())).toList();}
 private Document access(Long id,User user){var d=docs.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Document not found"));boolean reviewer=d.getApprovals().stream().anyMatch(a->a.getReviewer().getId().equals(user.getId()));if(user.getRole()!=Role.ADMINISTRATOR&&!d.getOwner().getId().equals(user.getId())&&!reviewer)throw new ApiException(HttpStatus.FORBIDDEN,"You cannot access this document");return d;} private void log(Document d,User u,String action,String detail){activity.save(new ActivityLog(d,u,action,detail));} private DocumentResponse map(Document d){return new DocumentResponse(d.getId(),d.getTitle(),d.getDescription(),d.getOriginalFileName(),d.getFileSize(),d.getStatus(),d.getOwner().getFullName(),d.getCreatedAt(),d.getApprovals().stream().map(a->new Reviewer(a.getReviewer().getId(),a.getReviewer().getFullName(),a.getDecision())).toList());}
}
